<template><view class="page"><view class="bar"><text @tap="back">‹</text><text>新建相册</text><text @tap="save">保存</text></view><view class="content"><text class="label">相册名称</text><input v-model="name" class="input" maxlength="200" placeholder="例如：2026 夏天"/><text class="hint">创建后可以上传照片，首张照片会自动成为相册封面。</text><button class="primary" :loading="saving" @tap="save">创建相册</button></view></view></template>
<script>import{createAlbum}from'../../services/api';export default{data(){return{spaceId:'',name:'',saving:false}},onLoad(q){this.spaceId=q.spaceId||''},methods:{async save(){if(this.saving)return;if(!this.name.trim()){uni.showToast({title:'请填写相册名称',icon:'none'});return}this.saving=true;try{const album=await createAlbum(this.spaceId,{name:this.name.trim()});uni.redirectTo({url:'/pages/album-detail/index?spaceId='+this.spaceId+'&albumId='+album.id+'&name='+encodeURIComponent(album.name)})}catch(e){uni.showToast({title:'创建失败，请检查空间权限',icon:'none'})}finally{this.saving=false}},back(){uni.navigateBack({delta:1})}}}</script>
<style scoped>.page{height:100vh;background:#f1eee5}.bar{height:calc(var(--status-bar-height) + 104rpx);padding:var(--status-bar-height) 28rpx 0;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;background:#fffdf8;color:#17211d;font-family:Georgia,'Songti SC',serif;font-size:28rpx;font-weight:700}.bar text:first-child{font-size:56rpx;line-height:52rpx}.bar text:last-child{color:#1d6347;font-family:inherit;font-size:22rpx}.content{padding:42rpx 28rpx}.label{display:block;color:#9b611f;font-size:18rpx;font-weight:800;letter-spacing:3rpx}.input{height:88rpx;margin-top:15rpx;padding:0 22rpx;border-radius:22rpx;background:#fffdf8;color:#17211d;font-size:25rpx}.hint{display:block;margin-top:18rpx;color:rgba(23,33,29,.48);font-size:20rpx;line-height:32rpx}.primary{height:86rpx;margin-top:35rpx;border-radius:22rpx;color:#fff;background:#163a2b;font-size:24rpx;font-weight:700}.primary:after{border:none}</style>
